scenarios.example_code:
import { sendNotification } from '@projexlight/sdk-notification';
await sendNotification({
  tenant_id, recipient: { kind: 'sms', value: customer.phone },
  template: { name: 'tech-eta-sms', version: '1.0.0' },
  variables: { tech_name, eta_start, eta_end, route_link },
});

import { sendNotification } from '@projexlight/sdk-notification';
await sendNotification({
  tenant_id, recipient: { persona_id },
  template: { name: 'invoice-reminder', version: '1.0.0' },
  scheduling: { respect_quiet_hours: true },
});

// template config:
{ name: 'tech-eta', channels: ['sms', 'email'], fallback_after_attempts: 1 }
// after SMS failure, engine sends email with the same variables.

subscribeEvents('storm.event.declared.v1', async (e) => {
  await sendNotification({
    tenant_id: e.tenant_id, recipient: { group: 'oncall' },
    template: { name: 'oncall-storm-page', version: '1.0.0' },
    variables: { event_kind: e.payload.kind, severity: e.payload.severity },
    scheduling: { ignore_quiet_hours: true },
  });
});

import { publishTemplate } from '@projexlight/sdk-notification';
await publishTemplate({
  tenant_id, name: 'tech-eta-sms', version: '1.1.0',
  locales: { 'en-US': '...', 'es-MX': '...' },
  channels: ['sms','email'],
});
